insert into public.changelog (datum, categorie, module, titel, omschrijving) values
  ('2026-07-28','verbeterd','Financieel','Prognose én besteed per component in de projectbewaking',
   'In de Financieel-tab van een dossier zie je nu per kostensoort — arbeid, onderaanneming, materiaal en inkoop — de prognose én het al bestede bedrag naast elkaar. Voorheen bleven onderaanneming en materiaal leeg zolang er nog niets was ingekocht, terwijl de begrote bedragen wél bestonden.');
